1	/**
2	 * The composed Angular CLI era migration: workspace configuration, TypeScript
3	 * configuration, package manifest and application source, lifted onto one
4	 * declared target cell and reported as a single itemised changeset.
5	 *
6	 * The changeset is the product. It records, per file, the bytes before and
7	 * after as digests and the individual changes that produced them, and it
8	 * separates application files from workspace files so that a count of changed
9	 * application files means what it says: source the application owns, changed by
10	 * a transform, not a version number edited in a manifest.
11	 */
12	
13	import { createHash } from 'node:crypto';
14	import {
15		alignAngularPackageManifest,
16		compareStrings,
17		type AngularTargetCell,
18		type DependencyChange,
19	} from './angular-target-cell.ts';
20	import { migrateAngularSourceModule, type SourceChange } from './angular-source-migration.ts';
21	import {
22		migrateModalContentParams,
23		type ModalContentParamsChange,
24		type ModuleResolution,
25	} from './modal-content-params-migration.ts';
26	import { migrateNgrxEffectDecorators, type NgrxEffectChange } from './ngrx-effects-migration.ts';
27	import {
28		migratePackageStyleImports,
29		type PackageExportsReading,
30		type StyleImportChange,
31	} from './package-exports-style-imports.ts';
32	import { migrateSentryV8Tracing, type SentryV8Change } from './sentry-v8-migration.ts';
33	import {
34		removeEntryComponents,
35		type EntryComponentsChange,
36	} from './entry-components-removal.ts';
37	import {
38		readDirectiveBindingDependencies,
39		reorderTemplateBindings,
40		type BindingReorderChange,
41		type DirectiveBindingReading,
42	} from './template-binding-reorder.ts';
43	import {
44		declareUndeclaredRuntimeDependencies,
45		undeclaredRuntimeDependencies,
46		type InstalledPackage,
47	} from './undeclared-runtime-dependency.ts';
48	import {
49		migrateAngularTsConfig,
50		migrateAngularWorkspace,
51		normalizeFragmentPath,
52		type ConfigChange,
53	} from './angular-workspace-migration.ts';
54	import {
55		isAngularCliOneWorkspace,
56		synthesizeAngularWorkspace,
57		type SynthesizedWorkspace,
58	} from './angular-cli-json-workspace-synthesis.ts';
59	import { tslintConfigRemovals } from './tslint-toolchain-removal.ts';
60	import { declareBuilderPackages } from './builder-package-declaration.ts';
61	
62	export type WorkspaceFile = Readonly<{ path: string; source: string }>;
63	
64	export type AngularMigrationInput = Readonly<{
65		packageManifest: WorkspaceFile;
66		workspaceConfig: WorkspaceFile;
67		tsConfig: WorkspaceFile;
68		/** Application source modules, as read from the workspace. */
69		sourceModules: readonly WorkspaceFile[];
70		/**
71		 * Component templates the application owns, kept apart from
72		 * {@link sourceModules} because they are not modules: no source transform
73		 * parses them, and the only capability that reads them reorders directive
74		 * bindings a component class proves are order-dependent. A tree that supplies
75		 * none has none reordered, which is a different thing from having none to
76		 * reorder.
77		 */
78		templates?: readonly WorkspaceFile[];
79		/**
80		 * Webpack fragments a wrapper builder reads, keyed by the path the workspace
81		 * writes for them. A fragment a target references but that is not supplied
82		 * here is reported unread and its wrapper builder is left in place.
83		 */
84		webpackFragments?: readonly WorkspaceFile[];
85		/**
86		 * Every workspace-relative path the tree carries, for capabilities that
87		 * decide a file should no longer exist. Only paths are needed: a file removed
88		 * because the toolchain that read it is gone does not have to be parsed. A
89		 * tree that supplies no list has no files removed.
90		 */
91		workspaceFiles?: readonly string[];
92		/**
93		 * Stylesheets the application owns, kept apart from {@link sourceModules}
94		 * because they are not modules: no source transform parses them, and the only
95		 * capability that reads them resolves package subpaths against an exports map.
96		 */
97		styleSheets?: readonly WorkspaceFile[];
98		/**
99		 * The published surface of packages whose stylesheet subpaths the application
100		 * imports, as read from the installed closure. A package not read here has its
101		 * style imports left exactly as they are.
102		 */
103		packageExports?: readonly PackageExportsReading[];
104		/**
105		 * The installed dependency closure, reduced to declarations and shipped
106		 * imports. Supplying it is what lets undeclared runtime dependencies be
107		 * detected; a tree that supplies none has none detected, which is a different
108		 * thing from having none.
109		 */
110		installedPackages?: readonly InstalledPackage[];
111		/** How the workspace resolves module specifiers written in its own source. */
112		moduleResolution?: ModuleResolution;
113	}>;
114	
115	export type MigratedFile = Readonly<{
116		path: string;
117		kind: 'application' | 'workspace';
118		changed: boolean;
119		sha256Before: string;
120		sha256After: string;
121		source: string;
122		changes: readonly string[];
123	}>;
124	
125	export type AngularMigration = Readonly<{
126		cell: string;
127		files: readonly MigratedFile[];
128		applicationFilesChanged: number;
129		workspaceFilesChanged: number;
130		applicationFilesScanned: number;
131		unhandled: readonly string[];
132		/**
133		 * Capabilities the migrated workspace deliberately no longer has, one line
134		 * per removal — a dropped lint target, a dropped configuration file, a
135		 * package the cell read and found no successor for. A reader is owed these by
136		 * name: they are the difference between the era workspace and this one that a
137		 * clean changeset would otherwise hide.
138		 */
139		declaredDifferences: readonly string[];
140		/** Files the migration decided the tree should no longer carry. */
141		removedFiles: readonly string[];
142	}>;
143	
144	function sha256(value: string): string {
145		return createHash('sha256').update(value).digest('hex');
146	}
147	
148	/**
149	 * Parse a workspace document only far enough to decide which format it is in.
150	 *
151	 * A document that is not JSON at all is handed on unparsed: the migration that
152	 * reads it next refuses it with the diagnosable error it already writes, and
153	 * duplicating that refusal here would report the same defect twice under two
154	 * different names.
155	 */
156	function safeParseJson(source: string): unknown {
157		try {
158			return JSON.parse(source) as unknown;
159		} catch {
160			return null;
161		}
162	}
163	
164	function describeConfigChange(change: ConfigChange): string {
165		if (change.to === null) return `removed ${change.path} (was ${change.from ?? 'absent'})`;
166		if (change.from === null) return `added ${change.path} = ${change.to}`;
167		return `${change.path}: ${change.from} -> ${change.to}`;
168	}
169	
170	function describeDependencyChange(change: DependencyChange): string {
171		const target = `${change.field}.${change.name}`;
172		return change.to === null
173			? `removed ${target} (was ${change.from}) — ${change.reason}`
174			: `${target}: ${change.from} -> ${change.to} — ${change.reason}`;
175	}
176	
177	function describeSourceChange(
178		change:
179			| SourceChange
180			| NgrxEffectChange
181			| SentryV8Change
182			| ModalContentParamsChange
183			| StyleImportChange,
184	): string {
185		return `line ${change.line}: ${change.kind} ${change.from} -> ${change.to}`;
186	}
187	
188	/**
189	 * An entry-components removal names no successor, because the property has
190	 * none: what a reader needs from it is which components the dropped list named,
191	 * so the proof that each is still reached can be checked against the literal.
192	 */
193	function describeEntryComponentsChange(change: EntryComponentsChange): string {
194		return `line ${change.line}: ${change.kind} of ${change.symbols.join(', ')}`;
195	}
196	
197	function describeBindingReorderChange(change: BindingReorderChange): string {
198		return (
199			`line ${change.line}: ${change.kind} on <${change.element}> (${change.directive}) — ` +
200			`${change.before.join(', ')} -> ${change.after.join(', ')}, forced by ${change.edges.join('; ')}`
201		);
202	}
203	
204	function file(
205		input: WorkspaceFile,
206		source: string,
207		kind: MigratedFile['kind'],
208		changes: readonly string[],
209	): MigratedFile {
210		return Object.freeze({
211			path: input.path,
212			kind,
213			changed: source !== input.source,
214			sha256Before: sha256(input.source),
215			sha256After: sha256(source),
216			source,
217			changes: Object.freeze([...changes]),
218		});
219	}
220	
221	/**
222	 * Apply every capability of the adapter to one workspace.
223	 *
224	 * Order matters in exactly one place: the workspace migration decides which
225	 * builder targets cannot be carried, and the packages those targets released
226	 * are what the manifest alignment then removes. Nothing else is ordered, and no
227	 * capability reads a file it was not handed.
228	 */
229	export function migrateAngularCliEraWorkspace(
230		input: AngularMigrationInput,
231		cell: AngularTargetCell,
232	): AngularMigration {
233		const unhandled: string[] = [];
234		const declaredDifferences: string[] = [];
235		const fragments: Record<string, string> = {};
236		for (const fragment of input.webpackFragments ?? [])
237			fragments[normalizeFragmentPath(fragment.path)] = fragment.source;
238		/**
239		 * A workspace in the pre-`angular.json` Angular CLI 1.x format is translated
240		 * into the modern one before anything else reads it. Every capability below
241		 * expects a `projects` map with `architect` targets, and the era document has
242		 * neither; synthesizing first is what lets the rest of the adapter run on a
243		 * CLI 1.x tree without one of them learning a second workspace format.
244		 */
245		let synthesis: SynthesizedWorkspace | null = null;
246		let workspaceConfigSource = input.workspaceConfig.source;
247		if (isAngularCliOneWorkspace(safeParseJson(input.workspaceConfig.source))) {
248			synthesis = synthesizeAngularWorkspace(
249				input.workspaceConfig.source,
250				cell,
251				input.workspaceConfig.path,
252			);
253			workspaceConfigSource = synthesis.config;
254			unhandled.push(...synthesis.unhandled);
255			declaredDifferences.push(...synthesis.declaredDifferences);
256		}
257		const workspace = migrateAngularWorkspace(workspaceConfigSource, cell, fragments);
258		unhandled.push(...workspace.unhandled);
259		declaredDifferences.push(...workspace.declaredDifferences);
260		const configRemovals = tslintConfigRemovals(input.workspaceFiles ?? [], cell);
261		declaredDifferences.push(...configRemovals.map((removal) => removal.reason));
262		for (const absorbed of workspace.absorbedFragments)
263			unhandled.push(
264				`${absorbed.path} was absorbed into the official builder and is no longer referenced by any ` +
265					`target; it was left in the tree rather than deleted. Absorbed capabilities: ` +
266					absorbed.capabilities.map((entry) => `${entry.kind} ${entry.detail}`).join(', '),
267			);
268		const manifest: unknown = JSON.parse(input.packageManifest.source);
269		if (typeof manifest !== 'object' || manifest === null || Array.isArray(manifest))
270			throw new Error('Angular migration: the package manifest is not a JSON object');
271		const aligned = alignAngularPackageManifest(
272			manifest as Readonly<Record<string, unknown>>,
273			cell,
274			workspace.removedPackages,
275		);
276		unhandled.push(...aligned.unhandled);
277		declaredDifferences.push(...aligned.declaredDifferences);
278		/**
279		 * Holes the closure carries are closed after the cell alignment, not before:
280		 * the cell decides which lines the workspace runs, and an undeclared edge is
281		 * declared at the line the cell read for it.
282		 */
283		const holes = undeclaredRuntimeDependencies(input.installedPackages ?? []);
284		const declared = declareUndeclaredRuntimeDependencies(aligned.manifest, holes, cell);
285		unhandled.push(...declared.unhandled);
286		declaredDifferences.push(...declared.declaredDifferences);
287		/**
288		 * The packages the migrated workspace's own targets name are declared last,
289		 * after every capability that decides which targets survive: a builder
290		 * declaration for a target the workspace migration removed would install a
291		 * toolchain nothing runs.
292		 */
293		const builders = declareBuilderPackages(declared.manifest, workspace.config, cell);
294		unhandled.push(...builders.unhandled);
295		const tsConfig = migrateAngularTsConfig(input.tsConfig.source, cell);
296		unhandled.push(...tsConfig.unhandled);
297		const files: MigratedFile[] = [
298			file(
299				input.packageManifest,
300				`${JSON.stringify(builders.manifest, null, 2)}\n`,
301				'workspace',
302				[
303					...aligned.changes.map(describeDependencyChange),
304					...declared.declarations.map(
305						(entry) =>
306							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
307					),
308					...builders.declarations.map(
309						(entry) =>
310							`added ${entry.field}.${entry.name} = ${entry.range} — ${entry.reason}`,
311					),
312				],
313			),
314			file(
315				synthesis === null
316					? input.workspaceConfig
317					: { path: synthesis.path, source: input.workspaceConfig.source },
318				workspace.config,
319				'workspace',
320				synthesis === null
321					? workspace.changes.map(describeConfigChange)
322					: [
323							`synthesized ${synthesis.path} from ${synthesis.replacedPath}, the pre-angular.json ` +
324								'Angular CLI 1.x workspace format; the digest recorded before is that file',
325							...synthesis.changes.map(describeConfigChange),
326							...workspace.changes.map(describeConfigChange),
327						],
328			),
329			file(
330				input.tsConfig,
331				tsConfig.config,
332				'workspace',
333				tsConfig.changes.map(describeConfigChange),
334			),
335		];
336		/**
337		 * Source capabilities run in sequence over each module, each one handed what
338		 * the last produced. They are independent — one rewrites module specifiers,
339		 * the next replaces a removed NgRx decorator — and a module is counted as
340		 * changed if any of them changed a byte of it.
341		 */
342		/**
343		 * One capability is not per-module and cannot be: rewriting a modal call site
344		 * without rewriting the content component it supplied is the silent failure
345		 * that capability exists to refuse. It runs over the whole tree first, and
346		 * what it produced is what the per-module capabilities then see.
347		 */
348		const modal = migrateModalContentParams(input.sourceModules, input.moduleResolution ?? {});
349		unhandled.push(...modal.unhandled);
350		const modalByPath = new Map(modal.files.map((entry) => [entry.path, entry]));
351		for (const module of [...input.sourceModules].sort((left, right) =>
352			compareStrings(left.path, right.path),
353		)) {
354			const modalFile = modalByPath.get(module.path);
355			const entrySource = modalFile?.source ?? module.source;
356			const migrated = migrateAngularSourceModule(module.path, entrySource);
357			const effects = migrateNgrxEffectDecorators(module.path, migrated.source);
358			const sentry = migrateSentryV8Tracing(module.path, effects.source);
359			/**
360			 * `entryComponents` is dropped last of the per-module capabilities, and the
361			 * order is not arbitrary: the capability proves, per literal, that every
362			 * component the property names is still reached by `declarations` or
363			 * `bootstrap` of the same literal, and it should see the literal as the
364			 * capabilities before it left it rather than as the era file wrote it.
365			 */
366			const entryComponents = removeEntryComponents(module.path, sentry.source);
367			unhandled.push(
368				...migrated.unhandled,
369				...effects.unhandled,
370				...sentry.unhandled,
371				...entryComponents.unhandled,
372			);
373			files.push(
374				file(module, entryComponents.source, 'application', [
375					...(modalFile?.changes ?? []).map(describeSourceChange),
376					...migrated.changes.map(describeSourceChange),
377					...effects.changes.map(describeSourceChange),
378					...sentry.changes.map(describeSourceChange),
379					...entryComponents.changes.map(describeEntryComponentsChange),
380				]),
381			);
382		}
383		/**
384		 * Templates are the last application capability, and it is cross-file by
385		 * nature: whether a call site's binding order is safe is a question about the
386		 * directive the element resolves to, read from that directive's own class.
387		 * The readings are taken from the modules as the per-module capabilities left
388		 * them, so a directive whose imports those capabilities rewrote still
389		 * resolves. A template no directive reading touches is carried through
390		 * unchanged and still counted, so the scanned total means what it says.
391		 */
392		const directiveReadings: DirectiveBindingReading[] = [];
393		for (const entry of files)
394			if (entry.kind === 'application' && entry.path.endsWith('.ts'))
395				directiveReadings.push(...readDirectiveBindingDependencies(entry.path, entry.source));
396		for (const template of [...(input.templates ?? [])].sort((left, right) =>
397			compareStrings(left.path, right.path),
398		)) {
399			const reordered = reorderTemplateBindings(template.path, template.source, directiveReadings);
400			unhandled.push(...reordered.unhandled);
401			files.push(
402				file(
403					template,
404					reordered.source,
405					'application',
406					reordered.changes.map(describeBindingReorderChange),
407				),
408			);
409		}
410		/**
411		 * Stylesheets are application files too, and a blocked package subpath is an
412		 * application file that no longer builds. Each is offered to every package
413		 * reading the caller supplied; a stylesheet no reading touches is carried
414		 * through unchanged and still counted, so the scanned total means what it says.
415		 */
416		for (const sheet of [...(input.styleSheets ?? [])].sort((left, right) =>
417			compareStrings(left.path, right.path),
418		)) {
419			let source = sheet.source;
420			const changes: string[] = [];
421			for (const reading of input.packageExports ?? []) {
422				const styles = migratePackageStyleImports(sheet.path, source, reading);
423				unhandled.push(...styles.unhandled);
424				declaredDifferences.push(...styles.declaredDifferences);
425				changes.push(...styles.changes.map(describeSourceChange));
426				source = styles.source;
427			}
428			files.push(file(sheet, source, 'application', changes));
429		}
430		const applicationFiles = files.filter((entry) => entry.kind === 'application');
431		return Object.freeze({
432			cell: cell.id,
433			files: Object.freeze(files),
434			applicationFilesChanged: applicationFiles.filter((entry) => entry.changed).length,
435			workspaceFilesChanged: files.filter((entry) => entry.kind === 'workspace' && entry.changed)
436				.length,
437			applicationFilesScanned: applicationFiles.length,
438			unhandled: Object.freeze([...new Set(unhandled)]),
439			declaredDifferences: Object.freeze([...new Set(declaredDifferences)]),
440			removedFiles: Object.freeze([
441				...configRemovals.map((removal) => removal.at),
442				...(synthesis === null ? [] : [synthesis.replacedPath]),
443			]),
444		});
445	}
