1	/**
2	 * `ModuleWithProviders` written without its type argument.
3	 *
4	 * Angular 10 removed the default from `ModuleWithProviders<T>`. Every era
5	 * annotation written as the bare name — the shape the Angular 4 docs taught for
6	 * a `forRoot` static — is a hard `TS2314` from that release on, and the type
7	 * argument it now needs is the NgModule the value configures.
8	 *
9	 * The argument is not guessable, so this capability never guesses it. It reads
10	 * it from the only two places the source states it:
11	 *
12	 * - an annotated variable whose initialiser is a static call on a class,
13	 *   `const routing: ModuleWithProviders = RouterModule.forRoot(...)`. The
14	 *   `ModuleWithProviders` a static factory returns is the module the static is
15	 *   declared on, so the receiver of the call *is* the argument.
16	 * - a static method's own return annotation inside a class,
17	 *   `static forRoot(): ModuleWithProviders`. The enclosing class is the module.
18	 *
19	 * Both readings resolve the name they emit as a binding: the receiver has to be
20	 * an identifier the module has a symbol for, so a call on a namespace member, a
21	 * computed member or an unbound name is refused rather than spelled out. Any
22	 * other position — a parameter, a field, an interface member, a call with no
23	 * receiver — is refused by name, because nothing in the source says what the
24	 * module is and an invented argument compiles into a lie.
25	 *
26	 * An annotation that already carries a type argument is not a site: the
27	 * capability reports nothing for an application written after Angular 10, which
28	 * is the check that it is not keyed to one.
29	 */
30	
31	import { compareStrings } from './angular-target-cell.ts';
32	import {
33		applySourceEdits,
34		forEachNode,
35		lineOf,
36		parseModule,
37		readModuleImports,
38		type AstNode,
39		type SemanticModule,
40		type SourceEdit,
41	} from './semantic-module.ts';
42	
43	const CAPABILITY = 'ModuleWithProviders type argument';
44	
45	/** The package that publishes the type, and the type that became generic. */
46	export const MODULE_WITH_PROVIDERS_PACKAGE = '@angular/core';
47	export const MODULE_WITH_PROVIDERS = 'ModuleWithProviders';
48	
49	export type ModuleWithProvidersChange = Readonly<{
50		kind: 'module-with-providers-type-argument';
51		line: number;
52		argument: string;
53		/** How the argument was read: from the initialiser, or from the enclosing class. */
54		readFrom: 'static-call-receiver' | 'enclosing-class';
55	}>;
56	
57	export type ModuleWithProvidersMigration = Readonly<{
58		path: string;
59		source: string;
60		changed: boolean;
61		changes: readonly ModuleWithProvidersChange[];
62		unhandled: readonly string[];
63	}>;
64	
65	type Reading = Readonly<{ argument: string; readFrom: ModuleWithProvidersChange['readFrom'] }>;
66	
67	/** The class a static call is made on, when the receiver is a bound identifier. */
68	function receiverModule(module: SemanticModule, initialiser: AstNode | null): string | null {
69		if (initialiser === null || initialiser.type !== 'CallExpression') return null;
70		const callee = initialiser.callee;
71		if (callee.type !== 'MemberExpression' || callee.computed || callee.optional) return null;
72		const receiver = callee.object;
73		if (receiver.type !== 'Identifier') return null;
74		if (module.symbolOf(receiver) === null) return null;
75		return receiver.name;
76	}
77	
78	/**
79	 * Where the module this annotation configures is stated, walking out from the
80	 * annotation to the declaration that owns it.
81	 */
82	function readArgument(module: SemanticModule, typeReference: AstNode): Reading | null {
83		const annotation = module.parentOf(typeReference);
84		if (annotation === null || annotation.type !== 'TSTypeAnnotation') return null;
85		const annotated = module.parentOf(annotation);
86		if (annotated === null) return null;
87		if (annotated.type === 'Identifier') {
88			const declarator = module.parentOf(annotated);
89			if (declarator === null || declarator.type !== 'VariableDeclarator') return null;
90			if (declarator.id !== annotated) return null;
91			const argument = receiverModule(module, declarator.init ?? null);
92			return argument === null ? null : { argument, readFrom: 'static-call-receiver' };
93		}
94		const method = module.parentOf(annotated);
95		if (method === null || method.type !== 'MethodDefinition' || !method.static) return null;
96		const body = module.parentOf(method);
97		if (body === null || body.type !== 'ClassBody') return null;
98		const declaration = module.parentOf(body);
99		if (declaration === null) return null;
100		if (declaration.type !== 'ClassDeclaration' && declaration.type !== 'ClassExpression') return null;
101		const id = declaration.id;
102		if (id === null || id === undefined || id.type !== 'Identifier') return null;
103		return { argument: id.name, readFrom: 'enclosing-class' };
104	}
105	
