const fs=require('fs'),path=require('path');
const dir='packages/frameworks/angular/src';
const files=fs.readdirSync(dir).filter(f=>f.endsWith('.ts'));
const graph={};
for(const f of files){const s=fs.readFileSync(path.join(dir,f),'utf8');
 const deps=[...s.matchAll(/from '\.\/([a-z0-9-]+)\.ts'/g)].map(m=>m[1]+'.ts');
 graph[f]=[...new Set(deps)];}
const seen=new Set();const stack=['angular-cli-era-migration.ts'];
while(stack.length){const c=stack.pop();if(seen.has(c))continue;seen.add(c);for(const d of graph[c]||[])stack.push(d);}
console.log('REACHED from era migration ('+seen.size+'):');
console.log([...seen].sort().join('\n'));
console.log('\nNOT REACHED:');
const nr=files.filter(f=>!seen.has(f)&&f!=='index.ts');
console.log(nr.sort().join('\n'));
// who imports the not-reached ones anywhere in src
console.log('\nIn-src importers of not-reached modules:');
for(const f of nr){const imps=files.filter(g=>g!=='index.ts'&&(graph[g]||[]).includes(f));console.log('  '+f+' <- '+(imps.length?imps.join(', '):'(nothing in src)'));}
