	why: string,
): TemplateI18nRuntimeDeclaration {
	return Object.freeze({
		declared: false,
		manifest,
		change: null,
		entryPoint: null,
		reading,
		declaredDifferences: Object.freeze([]),
		unhandled: Object.freeze([why]),
	});
